  sealed class ResultRow {
   public ZapretCheckRow Source{get;set;}public string Name{get;set;}public string Services{get;set;}public string State{get;set;}public int Milliseconds{get;set;}
  }
  CheckBox[] ServiceChoices(Panel parent){var choices=ZapretChecks.Services.Where(ZapretChecks.CanCheckZapret).Select(service=>new CheckBox{Content=service.CheckName,Tag=service.Id,IsChecked=service.Id=="youtube"||service.Id=="discord",Margin=new Thickness(0,0,16,12)}).ToArray();if(parent!=null)foreach(var choice in choices)parent.Children.Add(choice);return choices;}
  static ZapretSettings TestSettings(CheckBox[] checks){var ids=checks.Where(c=>c.IsChecked==true).Select(c=>(string)c.Tag).ToArray();var services=ZapretChecks.Selected(ids);return new ZapretSettings{ScopeText=String.Join("\n",services.Select(s=>s.Domains)),TestUrls=String.Join("\n",services.SelectMany(s=>s.Urls)),CheckServices=ids.ToList(),MatchMode="addresses"};}
  static ResultRow[] ResultRows(ZapretCheckReport report){return (report.Rows??new List<ZapretCheckRow>()).Where(row=>row!=null).Select(row=>new ResultRow{Source=row,Name=JournalStyle.Redact(row.Name),Services=String.Join(" · ",(row.Services??new List<ZapretServiceResult>()).Select(s=>s.Id+": "+(s.Access==ServiceAccess.Available?"доступен":s.Access==ServiceAccess.Unavailable?"недоступен":"не проверен"))),State=row.Checking?"Проверяется":String.IsNullOrEmpty(row.Error)?"Проверен":JournalStyle.Redact(row.Error),Milliseconds=row.TotalMilliseconds}).ToArray();}
  static ZapretCheckReport ReportSnapshot(ZapretCheckReport report){var json=new System.Web.Script.Serialization.JavaScriptSerializer{MaxJsonLength=Int32.MaxValue};return json.Deserialize<ZapretCheckReport>(json.Serialize(report));}
  void RefreshReport(DataGrid grid,ZapretCheckReport report){if(!closing&&!closeRequested&&grid.IsLoaded){grid.ItemsSource=ResultRows(report);lastReport=report;}}
  async Task ScanStrategies(ZapretCheckReport report,ZapretStrategy[] strategies,CancellationToken token,Action<string> progress,Action<ZapretCheckReport> save){await Task.Run(()=>session.Zapret.Scan(report,strategies,token,progress,save));}
  void EnsureCanTest(){if(session.Core.Running||session.Zapret.Running||session.Telegram.Running)throw new InvalidOperationException("Перед проверкой выключите VPN, Zapret и Telegram WS в этой копии.");}
