   Button stopEditor=Button("Остановить",()=>{if(scanCancellation!=null)scanCancellation.Cancel();},true);stopEditor.Visibility=Visibility.Collapsed;
   footer.Children.Add(AsyncButton("Сохранить копию",async()=>{form.IsEnabled=tabs.IsEnabled=false;try{var definition=await persist();actionFeedback.Text=status.Text="Сохранено: "+definition.Name+". Доступно во всех списках стратегий MCRF; пока не проверено.";}catch(Exception ex){actionFeedback.Text=status.Text="Не сохранено: "+JournalStyle.Redact(ex.Message);}finally{form.IsEnabled=tabs.IsEnabled=true;}}));
   footer.Children.Add(AsyncButton("Проверить копию",async()=>{if(!ChooseEditorServices(editorChecks))return;var settings=TestSettings(editorChecks);if(settings.CheckServices.Count==0)throw new InvalidOperationException("Выберите сервисы для проверки.");await PrepareTests();var definition=await persist();var profile=selectedProfile??session.State.ZapretProfiles.FirstOrDefault();var report=new ZapretCheckReport{Settings=settings,ServiceIds=settings.CheckServices,ProfileId=profile==null?null:profile.Id,ApplySettings=profile==null?settings:ZapretChecks.CopySettings(profile.Settings)};scanCancellation=new CancellationTokenSource();stopEditor.Visibility=Visibility.Visible;form.IsEnabled=tabs.IsEnabled=false;try{await ScanStrategies(report,new[]{CustomStrategies.Build(definition,catalog)},scanCancellation.Token,message=>Dispatcher.BeginInvoke(new Action(()=>status.Text=message)),r=>{ZapretChecks.Save(root,r);lastReport=r;});status.Text="Проверка завершена. Результаты сохранены; ничего не применено.";}finally{session.Zapret.Stop();scanCancellation.Dispose();scanCancellation=null;stopEditor.Visibility=Visibility.Collapsed;form.IsEnabled=tabs.IsEnabled=true;}}));footer.Children.Add(stopEditor);footer.Children.Add(Button("Результаты",ShowWorkspaceResults));
   foreach(Button button in footer.Children)button.Margin=new Thickness(0,0,10,0);Action footerLayout=()=>{bool compact=footer.ActualWidth>0&&footer.ActualWidth<420;footer.Columns=compact?1:Math.Max(1,footer.Children.Cast<UIElement>().Count(c=>c.Visibility!=Visibility.Collapsed));foreach(Button button in footer.Children)button.Margin=compact?new Thickness(0,0,0,8):new Thickness(0,0,10,0);};footer.SizeChanged+=(s,e)=>footerLayout();stopEditor.IsVisibleChanged+=(s,e)=>footerLayout();footerLayout();var catalogFeedback=Text("Загрузка стратегий…");catalogFeedback.Name="strategyCatalogFeedback";var retryCatalog=Button("Повторить загрузку",()=>{});retryCatalog.Name="strategyCatalogRetry";retryCatalog.Visibility=Visibility.Collapsed;var catalogInfo=Toolbar(retryCatalog);form.Children.Add(catalogFeedback);form.Children.Add(catalogInfo);Action loadCatalog=()=>LoadEditorCatalog(basis,items=>catalog=items,help=>editorHelp=help,catalogFeedback,retryCatalog);retryCatalog.Click+=(s,e)=>{session.InvalidateStrategies();loadCatalog();};loadCatalog();
