  sealed class EditorArgumentRow{public bool Enabled{get;set;}public string Flag{get;set;}public string Value{get;set;}public string Explanation{get;set;}}
  static string EditorValueDisplay(string value){string path=(value??"").Trim('"');if(path.EndsWith(".bin",StringComparison.OrdinalIgnoreCase)&&System.IO.Path.IsPathRooted(path))try{return System.IO.Path.GetFileName(path);}catch{}return value;}
  static string[] EditorOptions(string key){return key=="--dpi-desync"?new[]{"fake","fakeknown","multisplit","multidisorder","fakedsplit","fakeddisorder","hostfakesplit","fake,multisplit","fake,multidisorder","synack","syndata","rst","rstack","hopbyhop","destopt","ipfrag1","ipfrag2","udplen","tamper"}:key.Contains("fooling")?new[]{"none","md5sig","badseq","badsum","datanoack","ts","hopbyhop","hopbyhop2","md5sig,badseq"}:key.EndsWith("-mod")?new[]{"none","rnd","rndsni","dupsid","padencap","rnd,rndsni","sni=www.google.com"}:new string[0];}
  static string EditorDefaultValue(string key){return key=="--dpi-desync"?"fake":key=="--dpi-desync-repeats"?"3":key=="--dpi-desync-split-pos"?"2":key=="--filter-tcp"?"80,443":key=="--filter-udp"?"443":"";}
  static string EditorBlockHelp(string block){var filters=StrategyParameterEditor.Tokens(block).Where(t=>t.StartsWith("--filter-")).Select(t=>t.Replace("--filter-tcp=","TCP · порты ").Replace("--filter-udp=","UDP · порты "));return String.Join("\n",filters)+"\n\nБлок выбирает протокол и порты, затем применяет отмеченные аргументы обхода. Блоки проверяются по порядку; --new начинает следующий.\n\nДля UDP 443 обычно настраивают QUIC; для TCP 80/443 — HTTP/TLS. Режим --dpi-desync определяет способ обработки, остальные аргументы уточняют его. Совместимость зависит от режима: смотрите пояснение в таблице и проверяйте копию.\n\nСлева включайте нужные аргументы, справа редактируйте значения. Сохранение не означает успешную работу: проверка предлагается отдельно. Домены, IP и выходы назначаются в маршрутизации, не здесь.";}
  bool ChooseEditorServices(CheckBox[] checks){var previous=checks.Select(c=>c.IsChecked).ToArray();var dialog=Dialog("Сервисы проверки копии",560,440);var panel=new DockPanel{Margin=new Thickness(24)};var actions=Toolbar(Button("Проверить",()=>dialog.DialogResult=true),Button("Назад",()=>dialog.Close()));DockPanel.SetDock(actions,Dock.Bottom);panel.Children.Add(actions);var list=new StackPanel();foreach(var c in checks){if(c.Parent is Panel)((Panel)c.Parent).Children.Remove(c);list.Children.Add(c);}panel.Children.Add(new ScrollViewer{Content=list,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});dialog.Content=panel;bool accepted=dialog.ShowDialog()==true;if(!accepted)for(int i=0;i<checks.Length;i++)checks[i].IsChecked=previous[i];return accepted;}
  async void LoadEditorCatalog(ComboBox basis,Action<ZapretStrategy[]> ready,Action<string> helpReady,TextBlock feedback,Button retry){
   if(!basis.IsLoaded){RoutedEventHandler loaded=null;loaded=(s,e)=>{basis.Loaded-=loaded;LoadEditorCatalog(basis,ready,helpReady,feedback,retry);};basis.Loaded+=loaded;return;}
   basis.IsEnabled=false;retry.Visibility=Visibility.Collapsed;feedback.Text="Загрузка стратегий…";feedback.Visibility=Visibility.Visible;
   try{var items=await session.Strategies();var help=await session.EngineHelp();if(!closing&&basis.IsLoaded){ready(items);helpReady(help);basis.ItemsSource=items;basis.SelectedIndex=items.Length==0?-1:0;basis.IsEnabled=items.Length>0;basis.ToolTip=null;feedback.Text=items.Length==0?"Стратегий пока нет. Добавьте BAT или повторите загрузку.":"";feedback.Visibility=items.Length==0?Visibility.Visible:Visibility.Collapsed;retry.Visibility=items.Length==0?Visibility.Visible:Visibility.Collapsed;}}
   catch(Exception ex){if(!closing&&basis.IsLoaded){feedback.Text="Не удалось загрузить стратегии: "+JournalStyle.Redact(ex.Message);feedback.Visibility=Visibility.Visible;retry.Visibility=Visibility.Visible;basis.ToolTip=feedback.Text;}}
  }
 }
